(() => {
  const Z=window.Zucco,{icon:I,escape:E,badge:B,btn:BT}=Z;
  const metrics=items=>`<div class="metrics">${items.map(([label,value,note,icon='trend',tone=''])=>`<section class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon ${tone}">${I(icon)}</span></div><p class="metric-value ${tone==='danger'?'text-danger':''}">${value}</p><p class="metric-foot">${note}</p></section>`).join('')}</div>`;
  const table=(headers,rows,id='',footer='')=>`<div class="panel table-scroll"><table class="compact-table ext-table"><thead><tr>${headers.map(h=>`<th${Array.isArray(h)?` style="width:${h[1]}%"`:''}>${Array.isArray(h)?h[0]:h}</th>`).join('')}</tr></thead><tbody${id?` id="${id}-rows"`:''}>${rows||`<tr><td colspan="${headers.length}"><div class="empty-state">${I('search')}No matching records.</div></td></tr>`}</tbody></table>${footer?`<div class="table-footer">${footer}</div>`:''}</div>`;
  const link=(label,action)=>`<button class="link-button" type="button" data-action="${action}">${E(label)}</button>`;
  const tabs=(items,current,prefix)=>`<div class="view-tabs">${items.map(([id,label,count])=>`<button type="button" class="view-tab ${id===current?'active':''}" data-action="${prefix}:${id}" aria-pressed="${id===current}">${label}${count!==undefined?`<span class="count">${count}</span>`:''}</button>`).join('')}</div>`;
  const toolbar=(id,placeholder='Search records…',extra='')=>`<div class="toolbar"><label class="input-search">${I('search')}<input type="search" data-list-search="${id}" aria-label="${E(placeholder)}" placeholder="${E(placeholder)}" value="${E(Z.platform.filters[id]||'')}"></label>${extra}<div class="toolbar-spacer"></div><span class="caption" id="${id}-count"></span></div>`;
  const match=(id,...text)=>text.join(' ').toLowerCase().includes((Z.platform.filters[id]||'').toLowerCase());
  const status=value=>B(value,['Active','Approved','Available','Paid','Accepted','Delivered','Completed'].includes(value)?'success':['Frozen','Recruiting','Pending','Draft','Unknown','Trial'].includes(value)?'warning':value==='Debtor'||value==='Failed'?'danger':'');
  const field=(label,name,value='',type='text',extra='')=>`<label class="stack"><span class="field-label">${label}</span><input class="input field-control" name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;
  const select=(label,name,values,current='')=>`<label class="stack"><span class="field-label">${label}</span><select class="select field-control" name="${name}">${values.map(v=>{const[a,b]=Array.isArray(v)?v:[v,v];return `<option value="${E(a)}" ${a===current?'selected':''}>${E(b)}</option>`;}).join('')}</select></label>`;
  const form=(title,kind,fields,submit='Save changes',description='')=>Z.actionDialog(`<form id="ext-form" data-kind="${kind}"><div class="dialog-body"><div class="dialog-title-row"><h2 id="action-title">${title}</h2>${BT('','close-action','close','ghost small')}</div>${description?`<p>${description}</p>`:''}<div class="action-form">${fields}</div><p class="amount-error" id="ext-form-error" role="alert" hidden></p></div><div class="dialog-footer">${BT('Cancel','close-action')}<button class="btn primary" type="submit">${submit}</button></div></form>`);
  const panel=(title,body,action='')=>`<section class="panel"><div class="panel-heading"><h2>${title}</h2>${action}</div><div class="panel-body">${body}</div></section>`;
  const bars=values=>`<div class="horizontal-bars">${values.map(([label,value,percentage])=>`<div><div class="row between"><span>${label}</span><strong class="mono">${value}</strong></div><div class="bar-track"><span style="width:${percentage}%"></span></div></div>`).join('')}</div>`;
  Z.ui={metrics,table,link,tabs,toolbar,match,status,field,select,form,panel,bars};
  Z.extraHandlers={};Z.listRenderers={};
})();
